    12	// ErrInvalidVersion is returned by ParseRequests if one or more of the
    13	// requests in the input has a missing or invalid version marker.
    14	var ErrInvalidVersion error = &Error{Code: code.InvalidRequest, Message: "incorrect version marker"}
    15	
    16	// ParseRequests parses a single request or a batch of requests from JSON.
    17	//
    18	// If msg is syntactically valid apart from one or more of the requests having
    19	// a missing or invalid JSON-RPC version, ParseRequests returns ErrInvalidVersion
    20	// along with the parsed results.
    21	func ParseRequests(msg []byte) ([]*Request, error) {
    22		var req jmessages
    23		if err := req.parseJSON(msg); err != nil {
    24			return nil, err
    25		}
    26		var err error
    27		out := make([]*Request, len(req))
    28		for i, req := range req {
    29			if req.V != Version {
    30				err = ErrInvalidVersion
    31			}
    32			out[i] = &Request{
    33				id:     fixID(req.ID),
    34				method: req.M,
    35				params: req.P,
    36			}
    37		}
    38		return out, err
    39	}
