    41	// jmessages is either a single protocol message or an array of protocol
    42	// messages.  This handles the decoding of batch requests in JSON-RPC 2.0.
    43	type jmessages []*jmessage
    44	
    45	func (j jmessages) toJSON() ([]byte, error) {
    46		if len(j) == 1 && !j[0].batch {
    47			return j[0].toJSON()
    48		}
    49		var sb bytes.Buffer
    50		sb.WriteByte('[')
    51		for i, msg := range j {
    52			if i > 0 {
    53				sb.WriteByte(',')
    54			}
    55			bits, err := msg.toJSON()
    56			if err != nil {
    57				return nil, err
    58			}
    59			sb.Write(bits)
    60		}
    61		sb.WriteByte(']')
    62		return sb.Bytes(), nil
    63	}
    64	
    65	// N.B. Not UnmarshalJSON, because json.Unmarshal checks for validity early and
    66	// here we want to control the error that is returned.
    67	func (j *jmessages) parseJSON(data []byte) error {
    68		*j = (*j)[:0] // reset state
    69	
    70		// When parsing requests, validation checks are deferred: The only immediate
    71		// mode of failure for unmarshaling is if the request is not a valid object
    72		// or array.
    73		var msgs []json.RawMessage
    74		var batch bool
    75		if firstByte(data) != '[' {
    76			msgs = append(msgs, nil)
    77			if err := json.Unmarshal(data, &msgs[0]); err != nil {
    78				return errInvalidRequest
    79			}
    80		} else if err := json.Unmarshal(data, &msgs); err != nil {
    81			return errInvalidRequest
    82		} else {
    83			batch = true
    84		}
    85	
    86		// Now parse the individual request messages, but do not fail on errors.  We
    87		// know that the messages are intact, but validity is checked at usage.
    88		for _, raw := range msgs {
    89			req := new(jmessage)
    90			req.parseJSON(raw)
    91			req.batch = batch
    92			*j = append(*j, req)
    93		}
    94		return nil
    95	}
