    97	// jmessage is the transmission format of a protocol message.
    98	type jmessage struct {
    99		V  string          // must be Version
   100		ID json.RawMessage // may be nil
   101	
   102		// Fields belonging to request or notification objects
   103		M string
   104		P json.RawMessage // may be nil
   105	
   106		// Fields belonging to response or error objects
   107		E *Error          // set on error
   108		R json.RawMessage // set on success
   109	
   110		// N.B.: In a valid protocol message, M and P are mutually exclusive with E
   111		// and R. Specifically, if M != "" then E and R must both be unset. This is
   112		// checked during parsing.
   113	
   114		batch bool  // this message was part of a batch
   115		err   error // if not nil, this message is invalid and err is why
   116	}
