   118	// isValidID reports whether v is a valid JSON encoding of a request ID.
   119	// Precondition: v is a valid JSON value, or empty.
   120	func isValidID(v json.RawMessage) bool {
   121		if len(v) == 0 || isNull(v) {
   122			return true // nil or empty is OK, as is "null"
   123		} else if v[0] == '"' || v[0] == '-' || (v[0] >= '0' && v[0] <= '9') {
   124			return true // strings and numbers are OK
   125	
   126			// N.B. This definition does not reject fractional numbers, although the
   127			// spec says numeric IDs should not have fractional parts.
   128		}
   129		return false // anything else is garbage
   130	}
