   136	func (j *jmessage) toJSON() ([]byte, error) {
   137		var sb bytes.Buffer
   138		sb.WriteString(`{"jsonrpc":"2.0"`)
   139		if len(j.ID) != 0 {
   140			sb.WriteString(`,"id":`)
   141			sb.Write(j.ID)
   142		}
   143		switch {
   144		case j.M != "":
   145			m, err := json.Marshal(j.M)
   146			if err != nil {
   147				return nil, err
   148			}
   149			sb.WriteString(`,"method":`)
   150			sb.Write(m)
   151			if len(j.P) != 0 {
   152				sb.WriteString(`,"params":`)
   153				sb.Write(j.P)
   154			}
   155	
   156		case len(j.R) != 0:
   157			sb.WriteString(`,"result":`)
   158			sb.Write(j.R)
   159	
   160		case j.E != nil:
   161			e, err := json.Marshal(j.E)
   162			if err != nil {
   163				return nil, err
   164			}
   165			sb.WriteString(`,"error":`)
   166			sb.Write(e)
   167		}
   168	
   169		sb.WriteByte('}')
   170		return sb.Bytes(), nil
   171	}
