   173	func (j *jmessage) parseJSON(data []byte) error {
   174		// Unmarshal into a map so we can check for extra keys.  The json.Decoder
   175		// has DisallowUnknownFields, but fails decoding eagerly for fields that do
   176		// not map to known tags. We want to fully parse the object so we can
   177		// propagate the "id" in error responses, if it is set. So we have to decode
   178		// and check the fields ourselves.
   179	
   180		var obj map[string]json.RawMessage
   181		if err := json.Unmarshal(data, &obj); err != nil {
   182			j.fail(code.ParseError, "request is not a JSON object")
   183			return j.err
   184		}
   185	
   186		*j = jmessage{}    // reset content
   187		var extra []string // extra field names
   188		for key, val := range obj {
   189			switch key {
   190			case "jsonrpc":
   191				if json.Unmarshal(val, &j.V) != nil {
   192					j.fail(code.ParseError, "invalid version key")
   193				}
   194			case "id":
   195				if isValidID(val) {
   196					j.ID = val
   197				} else {
   198					j.fail(code.InvalidRequest, "invalid request ID")
   199				}
   200			case "method":
   201				if json.Unmarshal(val, &j.M) != nil {
   202					j.fail(code.ParseError, "invalid method name")
   203				}
   204			case "params":
   205				// As a special case, reduce "null" to nil in the parameters.
   206				// Otherwise, require per spec that val is an array or object.
   207				if !isNull(val) {
   208					j.P = val
   209				}
   210				if fb := firstByte(j.P); fb != 0 && fb != '[' && fb != '{' {
   211					j.fail(code.InvalidRequest, "parameters must be array or object")
   212				}
   213			case "error":
   214				if json.Unmarshal(val, &j.E) != nil {
   215					j.fail(code.ParseError, "invalid error value")
   216				}
   217			case "result":
   218				j.R = val
   219			default:
   220				extra = append(extra, key)
   221			}
   222		}
   223	
   224		// Report an error if request/response fields overlap.
   225		if j.M != "" && (j.E != nil || j.R != nil) {
   226			j.fail(code.InvalidRequest, "mixed request and reply fields")
   227		}
   228	
   229		// Report an error for extraneous fields.
   230		if j.err == nil && len(extra) != 0 {
   231			j.err = Errorf(code.InvalidRequest, "extra fields in request").WithData(extra)
   232		}
   233		return nil
   234	}
