   236	// isRequestOrNotification reports whether j is a request or notification.
   237	func (j *jmessage) isRequestOrNotification() bool { return j.M != "" && j.E == nil && j.R == nil }
   238	
   239	// isNotification reports whether j is a notification
   240	func (j *jmessage) isNotification() bool { return j.isRequestOrNotification() && fixID(j.ID) == nil }
   241	
   242	// fixID filters id, treating "null" as a synonym for an unset ID.  This
   243	// supports interoperation with JSON-RPC v1 where "null" is used as an ID for
   244	// notifications.
   245	func fixID(id json.RawMessage) json.RawMessage {
   246		if !isNull(id) {
   247			return id
   248		}
   249		return nil
   250	}
   251	
   252	// sender is the subset of channel.Channel needed to send messages.
   253	type sender interface{ Send([]byte) error }
   254	
   255	// receiver is the subset of channel.Channel needed to receive messages.
   256	type receiver interface{ Recv() ([]byte, error) }
   257	
   258	// encode marshals rsps as JSON and forwards it to the channel.
   259	func encode(ch sender, rsps jmessages) (int, error) {
   260		bits, err := rsps.toJSON()
   261		if err != nil {
   262			return 0, err
   263		}
   264		return len(bits), ch.Send(bits)
   265	}
   266	
   267	// isNull reports whether msg is exactly the JSON "null" value.
   268	func isNull(msg json.RawMessage) bool {
   269		return len(msg) == 4 && msg[0] == 'n' && msg[1] == 'u' && msg[2] == 'l' && msg[3] == 'l'
   270	}
   271	
   272	// firstByte returns the first non-whitespace byte of data, or 0 if there is none.
   273	func firstByte(data []byte) byte {
   274		clean := bytes.TrimSpace(data)
   275		if len(clean) == 0 {
   276			return 0
   277		}
   278		return clean[0]
   279	}
