   281	// strictFielder is an optional interface that can be implemented by a type to
   282	// reject unknown fields when unmarshaling from JSON.  If a type does not
   283	// implement this interface, unknown fields are ignored.
   284	type strictFielder interface {
   285		DisallowUnknownFields()
   286	}
   287	
   288	// StrictFields wraps a value v to require unknown fields to be rejected when
   289	// unmarshaling from JSON.
   290	//
   291	// For example:
   292	//
   293	//       var obj RequestType
   294	//       err := req.UnmarshalParams(jrpc2.StrictFields(&obj))`
   295	//
   296	func StrictFields(v interface{}) interface{} { return &strict{v: v} }
   297	
   298	type strict struct{ v interface{} }
   299	
   300	func (s *strict) UnmarshalJSON(data []byte) error {
   301		dec := json.NewDecoder(bytes.NewReader(data))
   302		dec.DisallowUnknownFields()
   303		return dec.Decode(s.v)
   304	}
