   155	func TestClient_contextCancellation(t *testing.T) {
   156		defer leaktest.Check(t)()
   157	
   158		started := make(chan struct{})
   159		stopped := make(chan struct{})
   160		cpipe, spipe := channel.Direct()
   161		srv := NewServer(hmap{
   162			"Hang": methodFunc(func(ctx context.Context, _ *Request) (interface{}, error) {
   163				close(started) // signal that the method handler is running
   164				select {
   165				case <-stopped:
   166					t.Log("Server unblocked by client completing")
   167					return true, nil
   168				case <-time.After(10 * time.Second):
   169					t.Error("Server timed out before completion")
   170					return false, nil
   171				}
   172			}),
   173		}, nil).Start(spipe)
   174		c := NewClient(cpipe, nil)
   175		defer func() {
   176			c.Close()
   177			srv.Wait()
   178		}()
   179	
   180		// Start a call that will hang around until a timer expires or an explicit
   181		// cancellation is received.
   182		ctx, cancel := context.WithCancel(context.Background())
   183		req, err := c.req(ctx, "Hang", nil)
   184		if err != nil {
   185			t.Fatalf("c.req(Hang) failed: %v", err)
   186		}
   187		rsps, err := c.send(ctx, jmessages{req})
   188		if err != nil {
   189			t.Fatalf("c.send(Hang) failed: %v", err)
   190		}
   191	
   192		// Wait for the handler to start so that we don't race with calling the
   193		// handler on the server side, then cancel the context client-side.
   194		<-started
   195		cancel()
   196	
   197		// The call should fail client side, in the usual way for a cancellation.
   198		rsp := rsps[0]
   199		rsp.wait()
   200		close(stopped)
   201		if err := rsp.Error(); err != nil {
   202			if err.Code != code.Cancelled {
   203				t.Errorf("Response error for %q: got %v, want %v", rsp.ID(), err, code.Cancelled)
   204			}
   205		} else {
   206			t.Errorf("Response for %q: unexpectedly succeeded", rsp.ID())
   207		}
