import (
	"encoding/json"
	"fmt"
)

// Copied from json.go to test the parsing
type jmessage struct {
	V     string          // must be Version
	ID    json.RawMessage // may be nil
	M     string
	P     json.RawMessage // may be nil
	E     *Error
	R     json.RawMessage // set on success
	batch bool
	err   error // if not nil, this message is invalid and err is why
}

type Error struct {
	Code    int         `json:"code"`
	Message string      `json:"message"`
	Data    interface{} `json:"data,omitempty"`
}

func (e *Error) Error() string {
	return fmt.Sprintf("[%d] %s", e.Code, e.Message)
}

func (j *jmessage) fail(code int, msg string) {
	j.err = &Error{Code: code, Message: msg}
}

func isValidID(v json.RawMessage) bool {
	if len(v) == 0 || isNull(v) {
		return true
	} else if v[0] == '"' || v[0] == '-' || (v[0] >= '0' && v[0] <= '9') {
		return true
	}
	return false
}

func isNull(msg json.RawMessage) bool {
	return len(msg) == 4 && msg[0] == 'n' && msg[1] == 'u' && msg[2] == 'l' && msg[3] == 'l'
}

func firstByte(data []byte) byte {
	clean := data // simplified for testing
	for i := range clean {
		if clean[i] > ' ' {
			return clean[i]
		}
	}
	return 0
}

func (j *jmessage) parseJSON(data []byte) error {
	var obj map[string]json.RawMessage
	if err := json.Unmarshal(data, &obj); err != nil {
		j.fail(-32700, "request is not a JSON object")
		return j.err
	}

	*j = jmessage{}
	var extra []string
	for key, val := range obj {
		switch key {
		case "jsonrpc":
			if json.Unmarshal(val, &j.V) != nil {
				j.fail(-32700, "invalid version key")
			}
		case "id":
			if isValidID(val) {
				j.ID = val
			} else {
				j.fail(-32600, "invalid request ID")
			}
		case "method":
			if json.Unmarshal(val, &j.M) != nil {
				j.fail(-32700, "invalid method name")
			}
		case "params":
			if !isNull(val) {
				j.P = val
			}
			if fb := firstByte(j.P); fb != 0 && fb != '[' && fb != '{' {
				j.fail(-32600, "parameters must be array or object")
			}
		case "error":
			if json.Unmarshal(val, &j.E) != nil {
				j.fail(-32700, "invalid error value")
			}
		case "result":
			j.R = val
		default:
			extra = append(extra, key)
		}
	}

	// Report an error if request/response fields overlap.
	if j.M != "" && (j.E != nil || j.R != nil) {
		j.fail(-32600, "mixed request and reply fields")
	}

	// Report an error for extraneous fields.
	if j.err == nil && len(extra) != 0 {
		j.err = &Error{Code: -32600, Message: "extra fields in request"}
		j.err.Data = extra
	}
	return nil
}

