	reqs, err := jrpc2.ParseRequests([]byte(input))
	if err != nil {
		if expectError {
			fmt.Printf("  ✓ Got expected error: %v\n", err)
		} else {
			fmt.Printf("  ✗ Unexpected error: %v\n", err)
		}
	} else {
		if expectError {
			fmt.Printf("  ✗ Expected error but got none\n")
		} else {
			fmt.Printf("  ✓ No error (as expected)\n")
			if len(reqs) > 0 {
				for i, req := range reqs {
					fmt.Printf("    Request %d: ID=%q, Method=%q, IsNotification=%v\n", 
						i, req.ID(), req.Method(), req.IsNotification())
				}
			}
		}
	}
}

func main() {
	// Valid requests
	testCase("Valid request with numeric ID", `{"jsonrpc":"2.0","id":1,"method":"test"}`, false)
	testCase("Valid request with string ID", `{"jsonrpc":"2.0","id":"abc","method":"test"}`, false)
	testCase("Valid notification (no ID)", `{"jsonrpc":"2.0","method":"notify"}`, false)
	testCase("Valid notification with null ID", `{"jsonrpc":"2.0","id":null,"method":"notify"}`, false)
	testCase("Valid request with params", `{"jsonrpc":"2.0","id":1,"method":"test","params":{"x":1}}`, false)

	// Invalid requests - extra fields
	testCase("Extra field 'bogus'", `{"jsonrpc":"2.0","id":1,"method":"test","bogus":true}`, true)
	testCase("Multiple extra fields", `{"jsonrpc":"2.0","id":1,"method":"test","a":1,"b":2}`, true)

	// Invalid requests - missing required fields
	testCase("Missing method field", `{"jsonrpc":"2.0","id":1}`, true)
	testCase("Only jsonrpc field", `{"jsonrpc":"2.0"}`, true)

	// Invalid requests - invalid ID structure
	testCase("Invalid ID (object)", `{"jsonrpc":"2.0","id":{"key":"value"},"method":"test"}`, true)
	testCase("Invalid ID (array)", `{"jsonrpc":"2.0","id":[1,2],"method":"test"}`, true)

	// Invalid JSON
	testCase("Malformed JSON", `{`, true)
	testCase("Invalid batch", `[{"bad"{]`, true)

	// Batch requests
	testCase("Valid batch", `[{"jsonrpc":"2.0","id":1,"method":"A"},{"jsonrpc":"2.0","id":2,"method":"B"}]`, false)
	testCase("Batch with one invalid", `[{"jsonrpc":"2.0","id":1,"method":"A"},{"jsonrpc":"2.0","id":2,"method":"B","extra":true}]`, true)

	// Edge cases
	testCase("Empty array (valid empty batch)", `[]`, false)
	testCase("Object without version", `{"id":1,"method":"test"}`, true) // This will fail on version check
}
"}

