func TestParseRequest(t *testing.T) {
	tests := []struct {
		name    string
		input   string
		wantID  string
		wantMeth string
		wantErr bool
	}{
		{
			name:     "valid request",
			input:    `{"jsonrpc":"2.0","id":1,"method":"test"}`,
			wantID:   "1",
			wantMeth: "test",
			wantErr:  false,
		},
		{
			name:     "valid notification",
			input:    `{"jsonrpc":"2.0","method":"notify"}`,
			wantID:   "",
			wantMeth: "notify",
			wantErr:  false,
		},
		{
			name:     "invalid JSON",
			input:    `{`,
			wantID:   "",
			wantMeth: "",
			wantErr:  true,
		},
		{
			name:     "extra fields",
			input:    `{"jsonrpc":"2.0","id":1,"method":"test","bogus":true}`,
			wantID:   "",
			wantMeth: "",
			wantErr:  true,
		},
		{
			name:     "batch (multiple requests)",
			input:    `[{"jsonrpc":"2.0","id":1,"method":"A"},{"jsonrpc":"2.0","id":2,"method":"B"}]`,
			wantID:   "",
			wantMeth: "",
			wantErr:  true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := ParseRequest(tt.input)
			if (err != nil) != tt.wantErr {
				t.Errorf("ParseRequest() error = %v, wantErr %v", err, tt.wantErr)
				return
			}
			if !tt.wantErr {
				if got == nil {
					t.Fatal("ParseRequest() returned nil request")
				}
				if got.ID() != tt.wantID {
					t.Errorf("ParseRequest() ID = %q, want %q", got.ID(), tt.wantID)
				}
				if got.Method() != tt.wantMeth {
					t.Errorf("ParseRequest() Method = %q, want %q", got.Method(), tt.wantMeth)
				}
			}
		})
	}
}

func TestMustParseRequest(t *testing.T) {
	// Test that MustParseRequest succeeds on valid input
	req := MustParseRequest(t, `{"jsonrpc":"2.0","id":42,"method":"foo"}`)
	if req == nil {
		t.Fatal("MustParseRequest() returned nil")
	}
	if req.ID() != "42" {
		t.Errorf("MustParseRequest() ID = %q, want \"42\"", req.ID())
	}
	if req.Method() != "foo" {
		t.Errorf("MustParseRequest() Method = %q, want \"foo\"", req.Method())
	}

	// Test that MustParseRequest panics on invalid input
	defer func() {
		if r := recover(); r == nil {
			t.Error("MustParseRequest() did not panic on invalid input")
		}
	}()
	MustParseRequest(t, `{"jsonrpc":"2.0","id":1,"method":"test","bogus":true}`)
}

func TestParseRequest_IsNotification(t *testing.T) {
	// Test notification parsing
	req := MustParseRequest(t, `{"jsonrpc":"2.0","method":"notify"}`)
	if !req.IsNotification() {
		t.Error("Expected notification to be identified as such")
	}

	// Test regular request parsing
