+		{
+			name:     "valid notification",
+			input:    `{"jsonrpc":"2.0","method":"notify"}`,
+			wantID:   "",
+			wantMeth: "notify",
+			wantErr:  false,
+		},
+		{
+			name:     "invalid JSON",
+			input:    `{`,
