+					t.Errorf("ParseRequest() ID = %q, want %q", got.ID(), tt.wantID)
+				}
+				if got.Method() != tt.wantMeth {
+					t.Errorf("ParseRequest() Method = %q, want %q", got.Method(), tt.wantMeth)
+				}
+			}
+		})
+	}
+}
+
+func TestMustParseRequest(t *testing.T) {
+	// Test that MustParseRequest succeeds on valid input
+	req := MustParseRequest(t, `{"jsonrpc":"2.0","id":42,"method":"foo"}`)
+	if req == nil {
+		t.Fatal("MustParseRequest() returned nil")
+	}
+	if req.ID() != "42" {
+		t.Errorf("MustParseRequest() ID = %q, want \"42\"", req.ID())
+	}
+	if req.Method() != "foo" {
+		t.Errorf("MustParseRequest() Method = %q, want \"foo\"", req.Method())
+	}
+}
+
+func TestMustParseRequestFails(t *testing.T) {
+	// Test that MustParseRequest fails on invalid input
+	// We use a subtest to verify that t.Fatalf is called
+	t.Run("invalid_input", func(t *testing.T) {
+		// This will call t.Fatalf internally, which we can't catch directly
+		// So we just verify that ParseRequest returns an error for this input
+		_, err := ParseRequest(`{"jsonrpc":"2.0","id":1,"method":"test","bogus":true}`)
+		if err == nil {
+			t.Error("Expected ParseRequest to return an error for invalid input")
+		}
+	})
+}
+
+func TestParseRequest_IsNotification(t *testing.T) {
+	// Test notification parsing
+	req := MustParseRequest(t, `{"jsonrpc":"2.0","method":"notify"}`)
+	if !req.IsNotification() {
+		t.Error("Expected notification to be identified as such")
+	}
+
+	// Test regular request parsing
+	req = MustParseRequest(t, `{"jsonrpc":"2.0","id":1,"method":"test"}`)
+	if req.IsNotification() {
+		t.Error("Expected request with ID to not be a notification")
+	}
+}
+
+func TestParseRequest_Params(t *testing.T) {
+	// Test with object params
+	req := MustParseRequest(t, `{"jsonrpc":"2.0","id":1,"method":"test","params":{"x":1}}`)
+	if !req.HasParams() {
+		t.Error("Expected request to have params")
+	}
+
+	// Test without params
+	req = MustParseRequest(t, `{"jsonrpc":"2.0","id":1,"method":"test"}`)
+	if req.HasParams() {
+		t.Error("Expected request to not have params")
+	}
+
+	// Test with null params
+	req = MustParseRequest(t, `{"jsonrpc":"2.0","id":1,"method":"test","params":null}`)
+	if req.HasParams() {
+		t.Error("Expected request with null params to not have params")
+	}
+}
